using AttendanceApi.Data;
using AttendanceApi.DTOs;
using AttendanceApi.Models;
using AttendanceApi.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace AttendanceApi.Controllers;

[ApiController, Route("api/classes"), Authorize]
public class ClassesController(ApplicationDbContext db, AccessService access) : ControllerBase
{
    [HttpGet][ProducesResponseType(typeof(ResponseEnvelope<PageResult<ClassView>>), 200)] public async Task<IActionResult> List([FromQuery] ListQuery p) { var q = access.VisibleClasses(); if (!string.IsNullOrWhiteSpace(p.Search)) q = q.Where(x => x.Code.Contains(p.Search) || x.Name.Contains(p.Search)); return Ok(ApiResponse.Ok(await q.OrderBy(x => x.Id).Select(x => new { x.Id, x.Code, x.Name, x.SubjectId, x.LecturerId }).PageAsync(p))); }
    [HttpGet("{id:int}")][ProducesResponseType(typeof(ResponseEnvelope<ClassView>), 200)] public async Task<IActionResult> Get(int id) { var c = await access.Class(id, true); return Ok(ApiResponse.Ok(new { c.Id, c.Code, c.Name, c.SubjectId, c.LecturerId })); }
    [HttpPost, Authorize(Roles = Roles.Admin)][ProducesResponseType(typeof(ResponseEnvelope<ClassView>), 201)] public async Task<IActionResult> Create(ClassRequest r) { await References(r); var c = new CourseClass { Code = r.Code.Trim(), Name = r.Name.Trim(), SubjectId = r.SubjectId, LecturerId = r.LecturerId }; db.Classes.Add(c); await db.SaveChangesAsync(); return CreatedAtAction(nameof(Get), new { id = c.Id }, ApiResponse.Ok(new { c.Id, c.Code, c.Name, c.SubjectId, c.LecturerId })); }
    [HttpPut("{id:int}"), Authorize(Roles = Roles.Admin)][ProducesResponseType(typeof(ResponseEnvelope<ClassView>), 200)] public async Task<IActionResult> Update(int id, ClassRequest r) { var c = await db.Classes.Where(x => x.Id == id).Required(); ApiSupport.Require(!await db.Sessions.AnyAsync(x => x.CourseClassId == id), "Lớp đã có buổi học; không thể đổi thông tin.", 409); await References(r); c.Code = r.Code.Trim(); c.Name = r.Name.Trim(); c.SubjectId = r.SubjectId; c.LecturerId = r.LecturerId; await db.SaveChangesAsync(); return Ok(ApiResponse.Ok(new { c.Id, c.Code, c.Name, c.SubjectId, c.LecturerId })); }
    [HttpDelete("{id:int}"), Authorize(Roles = Roles.Admin)][ProducesResponseType(typeof(ResponseEnvelope<object>), 200)] public async Task<IActionResult> Delete(int id) { var c = await db.Classes.Where(x => x.Id == id).Required(); ApiSupport.Require(!await db.Sessions.AnyAsync(x => x.CourseClassId == id) && !await db.Enrollments.AnyAsync(x => x.CourseClassId == id), "Lớp đã được sử dụng.", 409); db.Classes.Remove(c); await db.SaveChangesAsync(); return Ok(ApiResponse.Ok()); }
    async Task References(ClassRequest r) { ApiSupport.Require(await db.Subjects.AnyAsync(x => x.Id == r.SubjectId) && await db.Lecturers.AnyAsync(x => x.Id == r.LecturerId), "Môn học hoặc giảng viên không tồn tại."); }
    [HttpGet("{classId:int}/students"), Authorize(Roles = "Admin,Lecturer")][ProducesResponseType(typeof(ResponseEnvelope<PageResult<Student>>), 200)] public async Task<IActionResult> Students(int classId, [FromQuery] ListQuery p) { await access.Class(classId); var q = db.Enrollments.Where(x => x.CourseClassId == classId).Select(x => x.Student); if (!string.IsNullOrWhiteSpace(p.Search)) q = q.Where(x => x.StudentCode.Contains(p.Search) || x.FullName.Contains(p.Search)); return Ok(ApiResponse.Ok(await q.OrderBy(x => x.Id).Select(x => new { x.Id, x.StudentCode, x.FullName, x.Email, x.UserId }).PageAsync(p))); }
    async Task LockRoster(int id) { await db.Database.ExecuteSqlInterpolatedAsync($"SELECT [Id] FROM [Classes] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={id}"); await access.Class(id); ApiSupport.Require(!await db.Sessions.AnyAsync(x => x.CourseClassId == id && x.AttendanceState != AttendanceState.Scheduled), "Danh sách lớp đã được sử dụng để điểm danh; không thay đổi trong bản demo.", 409); }
    [HttpPost("{classId:int}/students"), Authorize(Roles = Roles.Admin)][ProducesResponseType(typeof(ResponseEnvelope<EnrollmentView>), 201)] public async Task<IActionResult> Enroll(int classId, EnrollmentRequest r) { await using var tx = await db.Database.BeginTransactionAsync(); await LockRoster(classId); ApiSupport.Require(await db.Students.AnyAsync(x => x.Id == r.StudentId), "Sinh viên không tồn tại."); db.Enrollments.Add(new() { CourseClassId = classId, StudentId = r.StudentId }); await db.SaveChangesAsync(); await tx.CommitAsync(); return StatusCode(201, ApiResponse.Ok(new { courseClassId = classId, r.StudentId })); }
    [HttpDelete("{classId:int}/students/{studentId:int}"), Authorize(Roles = Roles.Admin)][ProducesResponseType(typeof(ResponseEnvelope<object>), 200)] public async Task<IActionResult> Unenroll(int classId, int studentId) { await using var tx = await db.Database.BeginTransactionAsync(); await LockRoster(classId); var e = await db.Enrollments.Where(x => x.CourseClassId == classId && x.StudentId == studentId).Required(); db.Remove(e); await db.SaveChangesAsync(); await tx.CommitAsync(); return Ok(ApiResponse.Ok()); }
}
